  const news = useMemo(() => { const seen = new Set(); const out = []; roster.forEach((p) => newsFor(p).forEach((n) => { if (!seen.has(n.x)) { seen.add(n.x); out.push({ p, n }); } })); return out; }, [roster]);
  const weeks = Array.from({ length: MAX_WEEK }, (_, i) => i + 1);
