  if (week <= REG_WEEKS) { const done = new Set(); const ms = []; LEAGUE_TEAMS.forEach((a) => { const b = LSCHED[week][a]; if (done.has(a)) return; done.add(a); done.add(b); ms.push(`${a} vs ${b}`); }); L.push(`Week ${week} league matchups: ${ms.join("; ")}`); }
  const pffLines = []; SLOTS.forEach((s0) => { const p = lineup[s0.k] ? byId[lineup[s0.k]] : null; if (!p) return; const m = matchup(p.t, week); if (m.bye) return; const d = pffProfile(m.opp, "def"); if (d) pffLines.push(`${m.opp} defense: coverage ${d.cov}, pass rush ${d.prsh}, run D ${d.rdef} (${d.n} games)`); const g = pffPlayer(p, week - 1); if (g) pffLines.push(`${p.n} last week: PFF ${g.g.off}, ${g.share}% of snaps`); }); if (pffLines.length) L.push(`PFF grades: ${[...new Set(pffLines)].join("; ")}`);
  L.push(`Power rankings (best lineup pts/wk): ${power.map((r) => `${r.rank}. ${r.team} ${fmt1(r.total)}`).join("; ")}`);
