// IMPORT (paste from Yahoo transactions)
// =============================================================================
function ImportSheet({ seen, onApply, onClose, apiBase, week, roster, teams, onScores, onLineup, onRoster, onMyRoster, onPff }) {
  const [kind, setKind] = useState("myroster"); const [txt, setTxt] = useState(""); const [imgs, setImgs] = useState([]); const img = imgs[0] || null; const [busy, setBusy] = useState(false); const [err, setErr] = useState(""); const [moves, setMoves] = useState(null); const [parsed, setParsed] = useState(null);
  const KINDS = [["myroster", "My roster"], ["transactions", "Transactions"], ["scores", "Scores"], ["roster", "Other team"], ["pffgrades", "PFF grades"]];
  const pickImages = (files) => { Array.from(files || []).slice(0, 4).forEach((f) => { const rd = new FileReader(); rd.onload = () => { const image = new Image(); image.onload = () => { const max = 1800; const sc = Math.min(1, max / Math.max(image.width, image.height)); const c = document.createElement("canvas"); c.width = Math.round(image.width * sc); c.height = Math.round(image.height * sc); c.getContext("2d").drawImage(image, 0, 0, c.width, c.height); setImgs((arr) => [...arr, c.toDataURL("image/jpeg", 0.85)].slice(0, 4)); }; image.src = rd.result; }; rd.readAsDataURL(f); }); };
  const read = async () => {
    setErr(""); setMoves(null); setParsed(null);
    if (kind === "transactions" && txt.trim() && !img) { const mv = parseYahooTx(txt); setMoves(mv.map((m) => ({ ...m, skip: seen.includes(m.key) }))); return; }
    setBusy(true);
    try { const apiKind = kind === "myroster" ? "roster" : kind; const r = await fetch(`${apiBase}/api/parse`, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ kind: apiKind, text: txt || undefined, images: imgs.length ? imgs.map((x) => x.split(",")[1]) : undefined, mediaType: "image/jpeg" }) }); const raw = await r.text(); let j; try { j = JSON.parse(raw); } catch (e) { throw new Error(r.status === 404 ? "The reader is not deployed yet (api/parse.js is missing on the server)." : `server ${r.status}: ${raw.slice(0, 120)}`); } if (!r.ok || j.error) throw new Error(j.error || `server ${r.status}`);
      if (kind === "transactions") { const arr = Array.isArray(j.data) ? j.data : []; const mv = arr.map((x) => { const team = LEAGUE_TEAMS.find((t) => t.toLowerCase() === String(x.team || "").toLowerCase()) || ""; const to = x.to ? LEAGUE_TEAMS.find((t) => t.toLowerCase() === String(x.to).toLowerCase()) || "" : ""; const pos = String(x.pos || "").toUpperCase() === "DST" ? "DEF" : String(x.pos || "").toUpperCase(); const nfl = YT[String(x.nfl || "").toLowerCase()] || String(x.nfl || "").toUpperCase(); const player = findPlayer(x.player || "", nfl, pos); const act = x.action === "trade" ? "trade" : x.action === "drop" ? "drop" : "add"; const t2 = act === "trade" ? (to || team) : team; return { key: `${x.date || ""}|${act}|${player.id}|${t2}`, date: x.date || "", act, player, team: t2, teams: [team, to].filter(Boolean) }; }); setMoves(mv.map((m) => ({ ...m, skip: seen.includes(m.key) }))); }
      else setParsed(j.data);
    } catch (e) { setErr(e.message); } finally { setBusy(false); }
  };
  const setMove = (i, patch) => setMoves((ms) => ms.map((m, j) => (j === i ? { ...m, ...patch, key: `${m.date}|${patch.act || m.act}|${m.player.id}|${patch.team != null ? patch.team : m.team}` } : m)));
  const ready = moves && moves.some((m) => !m.skip && m.team);
  const matchName = (x) => { const pos = String(x.pos || "").toUpperCase() === "DST" ? "DEF" : String(x.pos || "").toUpperCase(); const nfl = YT[String(x.nfl || "").toLowerCase()] || String(x.nfl || "").toUpperCase(); return findPlayer(x.player || "", nfl, pos); };
  return (
    <Sheet title="Import from Yahoo" sub="Paste the page text or upload a screenshot. You confirm before anything changes." onClose={onClose}>
      <div className="cb" style={{ paddingTop: 2 }}><div className="seg">{KINDS.map(([k, l]) => <button key={k} className={kind === k ? "on" : ""} onClick={() => { setKind(k); setMoves(null); setParsed(null); setErr(""); }}>{l}</button>)}</div></div>
      {!moves && !parsed && (<>
        <div className="field"><textarea className="notes" value={txt} onChange={(e) => setTxt(e.target.value)} placeholder={kind === "transactions" ? "Paste the Transactions page" : kind === "scores" ? "Paste the Scoreboard or Standings page" : "Or paste the roster page text"} style={{ minHeight: 120, fontSize: 14 }} /></div>
        <div className="btns" style={{ paddingTop: 0 }}>
          <label className="btn" style={{ display: "inline-flex", alignItems: "center", cursor: "pointer" }}>{imgs.length ? `Add screenshot (${imgs.length})` : "Upload screenshot"}<input type="file" accept="image/*" multiple style={{ display: "none" }} onChange={(e) => pickImages(e.target.files)} /></label>
          {imgs.map((im, i) => <img key={i} src={im} alt="" style={{ height: 42, borderRadius: 8, border: "1px solid var(--rule)" }} onClick={() => setImgs((arr) => arr.filter((_, j) => j !== i))} title="Tap to remove" />)}
          <button className="btn pri" disabled={busy || (!txt.trim() && !img)} onClick={read}>{busy ? "Reading" : "Read it"}</button>
        </div>
        {err && <div className="hint" style={{ color: "var(--stop)", paddingTop: 0 }}>{err}</div>}
        <div className="hint">{kind === "pffgrades" ? "Screenshot a PFF Premium game grade report (one team's offense or defense per shot; up to four shots at once). Grades feed player cards, Edge, matchups and the metrics table." : kind === "myroster" ? "The reliable way. Screenshot your whole Yahoo roster page (two shots if it is long). You will see exactly who gets added and removed before it applies, and it sets this week's lineup and IR to match." : kind === "transactions" ? "Adds, drops and trades. Already-logged moves are skipped, so paste the whole page every week." : kind === "scores" ? "Reads the weekly scoreboard (all seven matchups) or the standings table." : "Reads another team's roster page and replaces that team's roster here."}</div>
      </>)}
      {moves && (<>
        <div className="ssec"><span>{moves.length} move{moves.length === 1 ? "" : "s"} found</span><span>{moves.filter((m) => m.skip).length} already logged</span></div>
        {moves.length === 0 && <div className="empty">Could not find any player lines.</div>}
        <div className="card">{moves.map((m, i) => (
          <div key={i} className={"prow" + (m.skip ? " dim" : "")} style={{ gridTemplateColumns: "auto 1fr" }}>
            <Badge p={m.player} />
            <div><div className="pname"><span className="t">{m.player.n}</span>{m.player.custom && <span className="pill own">new</span>}{m.skip && <span className="pill own">logged</span>}</div>
              <div className="grid2" style={{ marginTop: 6, gap: 6 }}><select value={m.act} onChange={(e) => setMove(i, { act: e.target.value })} style={{ padding: "7px 8px", fontSize: 13 }}><option value="add">Added by</option><option value="drop">Dropped by</option><option value="trade">Traded to</option></select><select value={m.team} onChange={(e) => setMove(i, { team: e.target.value })} style={{ padding: "7px 8px", fontSize: 13, borderColor: m.team ? undefined : "var(--stop)" }}><option value="">Pick a team</option>{LEAGUE_TEAMS.map((t) => <option key={t} value={t}>{t}</option>)}</select></div>
              <div className="small muted" style={{ marginTop: 4 }}>{m.date || "no date"}</div></div>
          </div>))}</div>
        <div className="btns"><button className="btn pri" disabled={!ready} onClick={() => onApply(moves.filter((m) => !m.skip && m.team))}>Log {moves.filter((m) => !m.skip && m.team).length} move{moves.filter((m) => !m.skip && m.team).length === 1 ? "" : "s"}</button><button className="btn" onClick={() => setMoves(null)}>Back</button></div>
      </>)}
      {parsed && kind === "scores" && (() => { const st = parsed.standings; const arr = Array.isArray(parsed) ? parsed : []; const w = (arr[0] && arr[0].week) || week; return (<>
        <div className="ssec"><span>{st ? "Standings table" : `${arr.length} matchups, week ${w}`}</span></div>
        {st && <div className="hint">Standings are computed from scores here, so paste the weekly scoreboard instead; that gives every matchup's points.</div>}
        {!st && <div className="card">{arr.map((m, i) => <div key={i} className="scrow"><label><span>{m.a}</span><input readOnly value={m.sa != null ? m.sa : ""} /></label><span className="vs">vs</span><label><input readOnly value={m.sb != null ? m.sb : ""} /><span>{m.b}</span></label></div>)}</div>}
        {!st && <div className="btns"><button className="btn pri" onClick={() => { arr.forEach((m) => { const a = LEAGUE_TEAMS.find((t) => t.toLowerCase() === String(m.a || "").toLowerCase()), b = LEAGUE_TEAMS.find((t) => t.toLowerCase() === String(m.b || "").toLowerCase()); if (a && m.sa != null) onScores(w, a, String(m.sa)); if (b && m.sb != null) onScores(w, b, String(m.sb)); }); onClose(); }}>Save week {w} scores</button><button className="btn" onClick={() => setParsed(null)}>Back</button></div>}
      </>); })()}
      {parsed && kind === "lineup_disabled" && (() => { const L = {}; const used = new Set(); const miss = []; const slotCount = {}; (parsed.starters || []).forEach((x) => { const p = matchName(x); const mine = roster.find((r) => r.id === p.id); if (!mine) { miss.push(p.n); return; } let slot = String(x.slot || "").toUpperCase().replace("W/R/T", "FLEX").replace("D/ST", "DEF"); if (slot === "RB" || slot === "WR" || slot === "FLEX") { slotCount[slot] = (slotCount[slot] || 0) + 1; slot = slot + slotCount[slot]; } if (SLOTS.find((s0) => s0.k === slot) && !used.has(p.id)) { L[slot] = p.id; used.add(p.id); } }); const ir = (parsed.ir || []).map(matchName).filter((p) => roster.find((r) => r.id === p.id)); return (<>
        <div className="ssec"><span>Lineup read</span><span>{Object.keys(L).length} of 10 slots</span></div>
        <div className="card">{SLOTS.map((s0) => { const p = L[s0.k] ? roster.find((r) => r.id === L[s0.k]) : null; return p ? <PRow key={s0.k} p={p} week={week} badge={<Badge slot={s0.label} p={p} />} right={<Val p={p} week={week} />} /> : <div key={s0.k} className="prow dim"><Badge slot={s0.label} empty /><span className="pname">Not found</span><span /></div>; })}</div>
        {ir.length > 0 && <div className="hint">IR: {ir.map((p) => p.n).join(", ")}</div>}
        {miss.length > 0 && <div className="hint" style={{ color: "var(--stop)" }}>Not on your roster here: {miss.join(", ")}. Log the pickup under Transactions first, then read the lineup again.</div>}
        <div className="btns"><button className="btn pri" onClick={() => { onLineup(L, ir.map((p) => p.id)); onClose(); }}>Use this lineup</button><button className="btn" onClick={() => setParsed(null)}>Back</button></div>
      </>); })()}
      {parsed && kind === "myroster" && (() => { const items = (parsed.players || []).map((x) => ({ ...x, p: matchName(x) })); const ids = new Set(items.map((x) => x.p.id)); const adds = items.filter((x) => !roster.find((r) => r.id === x.p.id)); const drops = roster.filter((r) => !ids.has(r.id)); const ir = items.filter((x) => String(x.slot || "").toUpperCase() === "IR" || /^IR/i.test(String(x.status || ""))).map((x) => x.p.id); const L = {}; const cnt = {}; items.forEach((x) => { let slot = String(x.slot || "").toUpperCase().replace("W/R/T", "FLEX").replace("D/ST", "DEF"); if (slot === "BN" || slot === "IR" || !slot) return; if (slot === "RB" || slot === "WR" || slot === "FLEX") { cnt[slot] = (cnt[slot] || 0) + 1; slot = slot + cnt[slot]; } if (SLOTS.find((s0) => s0.k === slot)) L[slot] = x.p.id; }); return (<>
        <div className="ssec"><span>{items.length} players read</span><span>{adds.length} to add, {drops.length} to remove</span></div>
        {adds.length > 0 && <div className="card"><div className="ch"><h2 className="cond" style={{ fontSize: 14 }}>Adding</h2></div>{adds.map((x) => <PRow key={x.p.id} p={x.p} week={week} sub={x.p.custom ? "new to the app" : undefined} right={<Val p={x.p} label="per wk" />} />)}</div>}
        {drops.length > 0 && <div className="card"><div className="ch"><h2 className="cond" style={{ fontSize: 14 }}>Removing</h2></div>{drops.map((p) => <PRow key={p.id} p={p} week={week} right={<span className="pill d">Gone</span>} />)}</div>}
        {adds.length === 0 && drops.length === 0 && <div className="hint">Roster already matches. This will still set the lineup and IR.</div>}
        <div className="hint">Lineup read: {Object.keys(L).length} of 10 slots. IR: {ir.length ? ir.map((id) => (POOL_BY_ID[id] || {}).n || id).join(", ") : "none"}.</div>
        <div className="btns"><button className="btn pri" onClick={() => { onMyRoster(items.map((x) => x.p), L, ir, adds.map((x) => x.p), drops); onClose(); }}>Apply to my roster</button><button className="btn" onClick={() => setParsed(null)}>Back</button></div>
      </>); })()}
      {parsed && kind === "pffgrades" && (() => { const arr = Array.isArray(parsed) ? parsed : [parsed]; const ok = arr.filter((x) => x && x.team && x.players); return (<>
        <div className="ssec"><span>{ok.length} report{ok.length === 1 ? "" : "s"} read</span></div>
        {ok.map((x, i) => <div key={i} className="hint"><b>{x.team}</b> {x.side === "def" ? "defense" : "offense"} vs {x.opp || "?"}, week {x.week || week}: {x.players.length} players graded.</div>)}
        <div className="btns"><button className="btn pri" disabled={!ok.length} onClick={() => { onPff(ok.map((x) => ({ ...x, week: x.week || week }))); onClose(); }}>Save grades</button><button className="btn" onClick={() => setParsed(null)}>Back</button></div>
      </>); })()}
      {parsed && kind === "roster" && (() => { const players = (parsed.players || []).map(matchName); const L = {}; const cnt = {}; (parsed.players || []).forEach((x, i) => { let slot = String(x.slot || "").toUpperCase().replace("W/R/T", "FLEX").replace("D/ST", "DEF"); if (slot === "BN" || slot === "IR" || !slot) return; if (slot === "RB" || slot === "WR" || slot === "FLEX") { cnt[slot] = (cnt[slot] || 0) + 1; slot = slot + cnt[slot]; } if (SLOTS.find((s0) => s0.k === slot)) L[slot] = players[i].id; }); const [team, setTeam] = [parsed._team || (LEAGUE_TEAMS.find((t) => t.toLowerCase() === String(parsed.team || "").toLowerCase()) || ""), (t) => setParsed({ ...parsed, _team: t })]; return (<>
        <div className="ssec"><span>{players.length} players read</span></div>
        <div className="field"><label>Which team is this?</label><select value={team} onChange={(e) => setTeam(e.target.value)}><option value="">Pick a team</option>{LEAGUE_TEAMS.map((t) => <option key={t} value={t}>{t}</option>)}</select></div>
        <div className="card">{players.map((p, i) => <PRow key={p.id + i} p={p} week={week} right={<Val p={p} label="per wk" />} />)}</div>
        <div className="btns"><button className="btn pri" disabled={!team} onClick={() => { onRoster(team, players, Object.keys(L).length >= 8 ? L : null); onClose(); }}>{Object.keys(L).length >= 8 ? `Save ${team || "team"}'s roster and lineup` : `Replace ${team || "team"}'s roster`}</button><button className="btn" onClick={() => setParsed(null)}>Back</button></div>
      </>); })()}
    </Sheet>
  );
}
function WeeklySourcesSheet({ week, onSave, onClose, existing }) {
  const [fbg, setFbg] = useState(""); const [csv, setCsv] = useState(""); const [fi, setFi] = useState(""); const [gp, setGp] = useState(""); const [res, setRes] = useState(null);
  const GP_CITY = { seattle: "SEA", "new england": "NE", "la rams": "LAR", "san francisco": "SF", jacksonville: "JAX", cleveland: "CLE", cincinnati: "CIN", "tampa bay": "TB", indianapolis: "IND", baltimore: "BAL", pittsburgh: "PIT", atlanta: "ATL", houston: "HOU", buffalo: "BUF", carolina: "CAR", chicago: "CHI", tennessee: "TEN", "ny jets": "NYJ", detroit: "DET", "new orleans": "NO", "la chargers": "LAC", arizona: "ARI", "las vegas": "LV", miami: "MIA", philadelphia: "PHI", washington: "WAS", minnesota: "MIN", "green bay": "GB", "ny giants": "NYG", dallas: "DAL", "kansas city": "KC", denver: "DEN" };
  const parse = () => {
    const out = {}; let nf = 0, na = 0;
    if (fbg.trim()) { const lines = fbg.split(/\r?\n/).map((l) => l.trim()).filter(Boolean); for (let i = 0; i < lines.length; i++) { if (/^\d+\t?$/.test(lines[i]) && i + 2 < lines.length && /^(QB|RB|WR|TE|K|DEF)$/.test(lines[i + 2])) { const name = lines[i + 1], pos = lines[i + 2]; let nums = null; for (let j = i + 3; j < Math.min(lines.length, i + 9); j++) { const mm = lines[j].match(/^([\d.]+)\t([\d.]+)\t([\d.]+)$/); if (mm) { nums = [parseFloat(mm[1]), parseFloat(mm[2]), parseFloat(mm[3])]; break; } if (/^\d+\t?$/.test(lines[j])) break; } if (nums) { const p = pos === "DEF" ? POOL.find((x) => x.p === "DEF" && normName(x.n) === normName(name.split(" ").pop())) : POOL.find((x) => x.p === pos && normName(x.n) === normName(name)); if (p) { out[p.id] = { ...(out[p.id] || {}), fbg: nums }; nf++; } } } } }
    if (csv.trim()) { csv.split(/\r?\n/).forEach((line) => { const c = line.split(","); if (c.length < 4 || !/^\d+$/.test(c[0].trim())) return; const rank = parseInt(c[0], 10); const name = c[1].replace(/"/g, "").trim(); const pos = c[3].replace(/"/g, "").trim().toUpperCase().replace("DST", "DEF"); const p = POOL.find((x) => x.p === pos && normName(x.n) === normName(name)); if (p) { out[p.id] = { ...(out[p.id] || {}), ath: rank }; na++; } }); }
    let nfi = 0; if (fi.trim()) { const SEC = { QUARTERBACKS: "QB", "RUNNING BACKS": "RB", "WIDE RECEIVERS": "WR", "TIGHT ENDS": "TE", KICKERS: "K", "SPECIAL TEAMS": "DEF" }; let pos = null; fi.split(/\r?\n/).forEach((line) => { const t = line.trim(); if (SEC[t]) { pos = SEC[t]; return; } const m = t.match(/^(\d+),([A-Z]{2,3}),(.+),([\d.]+)$/); if (!m || !pos) return; const tm = YT[m[2].toLowerCase()] || m[2]; const p = pos === "DEF" ? POOL.find((x) => x.p === "DEF" && x.t === tm) : POOL.find((x) => x.p === pos && normName(x.n) === normName(m[3])); if (p) { out[p.id] = { ...(out[p.id] || {}), fi: parseFloat(m[4]) }; nfi++; } }); }
    const gpo = {}; let ngp = 0; if (gp.trim()) { gp.split(/\r?\n/).forEach((line) => { const c = line.split(/\t+|\s{2,}/).map((x) => x.trim()).filter(Boolean); if (c.length < 10) return; const t = GP_CITY[c[0].toLowerCase()]; if (!t) return; const v = c.slice(1, 10).map(parseFloat); if (v.some(isNaN)) return; gpo[t] = { comp: v[0], att: v[1], py: v[2], ptd: v[3], int: v[4], rush: v[5], ry: v[6], rtd: v[7], score: v[8] }; ngp++; }); }
    setRes({ out, nf, na, nfi, gpo, ngp });
  };
  return (
    <Sheet title={`Week ${week} sources`} sub="Paste Footballguys weekly projection pages and the FantasyPros/Athletic CSV. They join the weekly blend immediately." onClose={onClose}>
      <div className="field"><label>Footballguys weekly pages (copy each page, paste them all here)</label><textarea className="notes" value={fbg} onChange={(e) => setFbg(e.target.value)} placeholder={"1\nJosh Allen\nQB\n...\n18.2\t9.7\t28.5"} style={{ minHeight: 110, fontSize: 13 }} /></div>
      <div className="field"><label>Fantasy Index weekly CSV (the Hogg Heaven custom rankings)</label><textarea className="notes" value={fi} onChange={(e) => setFi(e.target.value)} placeholder={"QUARTERBACKS\n\nRank,Team,Name,Points\n1,CIN,Joe Burrow,22.1"} style={{ minHeight: 80, fontSize: 13 }} /></div>
      <div className="field"><label>Footballguys Game Predictor (paste the single table)</label><textarea className="notes" value={gp} onChange={(e) => setGp(e.target.value)} placeholder={"Seattle\t19.8\t30.2\t225.9\t1.5\t0.9\t29.2\t119.2\t1.0\t24.1"} style={{ minHeight: 70, fontSize: 13 }} /></div>
      <div className="field"><label>FantasyPros / The Athletic CSV</label><textarea className="notes" value={csv} onChange={(e) => setCsv(e.target.value)} placeholder="Rank,Player Name,Team,Position,..." style={{ minHeight: 80, fontSize: 13 }} /></div>
      {res && <div className="hint">Matched {res.nfi || 0} Fantasy Index, {res.nf} Footballguys projections, {res.na} expert ranks to players{res.ngp ? `, and ${res.ngp} team lines from the Game Predictor` : ""}.{existing ? " These add to what is already loaded for the week." : ""}</div>}
      <div className="btns"><button className="btn" onClick={parse} disabled={!fbg.trim() && !csv.trim() && !fi.trim() && !gp.trim()}>Check</button><button className="btn pri" disabled={!res || (!res.nf && !res.na && !res.nfi && !res.ngp)} onClick={() => { onSave(res.out, res.gpo); onClose(); }}>Save to week {week}</button></div>
    </Sheet>
  );
}

// =============================================================================
// MENU
// =============================================================================
function MenuSheet({ syncState, onSyncNow, onSyncPull, pushState, onPushOn, onPushCheck, state, settings, onSettings, onReset, onImport, onClose }) {
  const [mode, setMode] = useState("main"); const [txt, setTxt] = useState(""); const [msg, setMsg] = useState(""); const [confirm, setConfirm] = useState(false);
  const json = JSON.stringify({ ...state, chat: [] });
  const copy = async () => { try { await navigator.clipboard.writeText(json); setMsg("Copied. Paste it somewhere safe."); } catch (e) { setMsg("Copy blocked here. Select the text and copy it."); setMode("export"); } };
  return (
    <Sheet title="Settings and data" sub="Everything saves automatically. Export is your backup." onClose={onClose}>
      {mode === "main" && (<>
        <div className="field"><label>Look</label><div className="seg">{[["auto", "Auto"], ["light", "Call sheet"], ["dark", "Night game"]].map(([k, l]) => <button key={k} className={settings.theme === k ? "on" : ""} onClick={() => onSettings({ theme: k })}>{l}</button>)}</div></div>
        <div className="field"><label>Team logo</label>
          <div className="btns" style={{ padding: 0 }}>
            <label className="btn" style={{ display: "inline-flex", alignItems: "center", cursor: "pointer" }}>{settings.logo ? "Replace logo" : "Upload the DIMES logo"}<input type="file" accept="image/*" style={{ display: "none" }} onChange={(e) => { const f = e.target.files && e.target.files[0]; if (!f) return; const rd = new FileReader(); rd.onload = () => { const img = new Image(); img.onload = () => { const h = Math.min(160, img.height); const w = Math.round(img.width * (h / img.height)); const c = document.createElement("canvas"); c.width = w; c.height = h; c.getContext("2d").drawImage(img, 0, 0, w, h); onSettings({ logo: c.toDataURL("image/png") }); }; img.src = rd.result; }; rd.readAsDataURL(f); }} /></label>
            {settings.logo && <button className="btn" onClick={() => onSettings({ logo: null })}>Use the wordmark</button>}
          </div>
          <div className="small muted" style={{ marginTop: 6 }}>Transparent PNG works best on the navy bar. Kept at 160px tall.</div>
        </div>
        {!WEB && <div className="field"><label>Lines server</label><input value={settings.apiBase || DEFAULT_API} onChange={(e) => onSettings({ apiBase: e.target.value })} placeholder={DEFAULT_API} /><div className="small muted" style={{ marginTop: 6 }}>Your Vercel deployment. <a href={(settings.apiBase || DEFAULT_API)} target="_blank" rel="noreferrer" style={{ color: "var(--info)", fontWeight: 700 }}>Open the web version</a> if this view cannot reach it.</div></div>}
        {state.vegas && state.vegas.credits && <div className="hint" style={{ paddingTop: 0 }}>Odds API credits: {state.vegas.credits.used} used, {state.vegas.credits.remaining} remaining this month.</div>}
        <div className="field"><label>Sync across devices</label><input type="password" inputMode="numeric" value={settings.pin || ""} onChange={(e) => onSettings({ pin: e.target.value })} placeholder="Enter your DIMES_PIN" autoComplete="off" />
          <div className={"syncbox" + (syncState.ok === false ? " bad" : syncState.ok ? " good" : "")}><b>{settings.pin ? (syncState.msg || "Waiting for first sync") : "Off"}</b><small>{settings.pin ? "Every change pushes within two seconds; opening the app or returning to it pulls the newest save." : "Enter the PIN you set as DIMES_PIN in Vercel. Same PIN on your phone and desktop and they share one save."}</small></div>
          {settings.pin && <div className="btns" style={{ paddingTop: 6 }}><button className="btn sm pri" onClick={onSyncNow}>Push now</button><button className="btn sm" onClick={onSyncPull}>Pull from cloud</button></div>}
        </div>
        {WEB && <div className="field"><label>Notifications</label>
          <div className={"syncbox" + (pushState.on ? " good" : pushState.err ? " bad" : "")}><b>{pushState.on ? "On for this device" : pushState.err || "Off"}</b><small>Injury designation and depth-chart changes on your roster, checked every morning and whenever you open the app. On iPhone, add the site to your Home Screen first, then turn this on.</small></div>
          <div className="btns" style={{ paddingTop: 6 }}>{!pushState.on ? <button className="btn sm pri" onClick={onPushOn}>Turn on</button> : <button className="btn sm" onClick={onPushCheck}>Check now</button>}</div>
        </div>}
        <div className="field"><label>Where you bet</label><div className="chips">{[["FD", "FanDuel"], ["MGM", "BetMGM"], ["DK", "DraftKings"]].map(([k, l]) => <button key={k} className={"chip" + ((settings.books || []).includes(k) ? " on" : "")} onClick={() => { const b = settings.books || []; onSettings({ books: b.includes(k) ? b.filter((x) => x !== k) : [...b, k] }); }}>{l}</button>)}</div><div className="small muted" style={{ marginTop: 6 }}>Best prices and suggested bets only use these books. Everything still counts toward fair value.</div></div>
        <div className="field"><label>Trust in the projections: {Math.round((settings.modelW || 0.35) * 100)}%</label><input type="range" min="20" max="65" step="5" value={Math.round((settings.modelW || 0.35) * 100)} onChange={(e) => onSettings({ modelW: parseInt(e.target.value, 10) / 100 })} /><div className="small muted" style={{ marginTop: 6 }}>How much weight Fantasy Index and PFF get against the book's line when pricing a prop. The engine's backtest supports 35%. Push it up and you will see more plays and bigger edges; they will also be less reliable.</div></div>
        <div className="field"><label>Bankroll for stake sizing</label><input inputMode="decimal" value={settings.bankroll || 500} onChange={(e) => onSettings({ bankroll: parseFloat(e.target.value) || 0 })} /><div className="small muted" style={{ marginTop: 6 }}>Edge suggests quarter-Kelly stakes capped at 3% of this number.</div></div>
        <div className="field"><label>Auto lineup leans</label><div className="seg">{[["auto", "Auto"], ["mean", "Median"], ["floor", "Floor"], ["ceil", "Ceiling"]].map(([k, l]) => <button key={k} className={(settings.lineupMode || "auto") === k ? "on" : ""} onClick={() => onSettings({ lineupMode: k })}>{l}</button>)}</div><div className="small muted" style={{ marginTop: 6 }}>Auto favors ceiling when you are a clear underdog (under 40%), floor when you are a clear favorite (over 62%), and the median in between.</div></div>
        <div className="field"><label>Playoff teams</label><div className="seg">{[4, 6, 8].map((n) => <button key={n} className={(settings.playoffTeams || 6) === n ? "on" : ""} onClick={() => onSettings({ playoffTeams: n })}>{n}</button>)}</div></div>
        <div className="field"><label>Roster spots (not counting IR)</label><div className="seg">{[16, 17].map((n) => <button key={n} className={settings.rosterLimit === n ? "on" : ""} onClick={() => onSettings({ rosterLimit: n })}>{n}</button>)}</div><div className="small muted" style={{ marginTop: 6 }}>Set to 17 because you and Nothing Else Matters both added a DEF without dropping anyone.</div></div>
        <div className="btns"><button className="btn" onClick={copy}>Copy backup</button><button className="btn" onClick={() => setMode("export")}>Show backup</button><button className="btn" onClick={() => setMode("import")}>Restore</button></div>
        {msg && <div className="hint">{msg}</div>}
        <div className="hint">Sources: Yahoo ADP Sept 5; season projections from Fantasy Index, Footballguys and PFF (Sept 7, equal weight); weekly projections from Footballguys and The Athletic/FantasyPros ranks as they are added; Fantasy Index notes; Hogg Heaven draft plus logged moves; 2026 NFL schedule; Vegas lines when pulled.</div>
        <div className="ssec"><span>Danger zone</span></div>
        <div className="btns">{!confirm ? <button className="btn danger" onClick={() => setConfirm(true)}>Reset everything</button> : <><button className="btn danger" onClick={onReset}>Yes, wipe it</button><button className="btn" onClick={() => setConfirm(false)}>Cancel</button></>}</div>
        <div className="hint">Reset restores the 14 draft-day rosters plus the Sept 7 transactions, and clears lineups, scores, watchlist, notes and chat.</div>
      </>)}
      {mode === "export" && <div className="field"><label>Backup (select all, copy)</label><textarea readOnly value={json} style={{ minHeight: 160, fontSize: 11, fontFamily: "monospace" }} onFocus={(e) => e.target.select()} /><div className="btns" style={{ padding: "10px 0 0" }}><button className="btn" onClick={() => setMode("main")}>Back</button></div></div>}
      {mode === "import" && <div className="field"><label>Paste a backup</label><textarea value={txt} onChange={(e) => setTxt(e.target.value)} style={{ minHeight: 140, fontSize: 12, fontFamily: "monospace" }} placeholder='{"v":3,"roster":[...]}' />{msg && <div className="small" style={{ color: "var(--stop)", marginTop: 6 }}>{msg}</div>}<div className="btns" style={{ padding: "10px 0 0" }}><button className="btn pri" onClick={() => { if (!onImport(txt)) setMsg("That did not look like a Dimes backup."); }} disabled={!txt.trim()}>Restore</button><button className="btn" onClick={() => setMode("main")}>Back</button></div></div>}
    </Sheet>
  );
}
